<template><section class="module-page module-composed-page"><header class="module-heading"><div><h1>实训管理</h1><p>查看并维护用户课程实训环境。</p></div><el-button type="primary" icon="el-icon-plus" @click="createDialog=true">创建实训环境</el-button></header><div class="module-table-wrap"><el-table v-loading="loading" :data="environments" empty-text="暂无实训环境"><el-table-column prop="userId" label="用户" width="90" /><el-table-column prop="courseId" label="课程" width="90" /><el-table-column prop="agentId" label="处理服务器" min-width="180" /><el-table-column prop="actualState" label="状态" width="110" /><el-table-column label="操作" width="320" align="right"><template slot-scope="s"><el-button size="small" :disabled="pending(s.row)" @click="operate(s.row,'start')">启动</el-button><el-button size="small" :disabled="pending(s.row)" @click="operate(s.row,'stop')">停止</el-button><el-button size="small" type="warning" :disabled="pending(s.row)" @click="restore(s.row)">还原</el-button><el-button size="small" type="danger" :disabled="pending(s.row)||s.row.actualState!=='STOPPED'" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></div><el-dialog title="创建实训环境" :visible.sync="createDialog" width="520px"><el-form :model="form" label-width="100px"><el-form-item label="用户"><el-select v-model="form.userId" filterable style="width:100%"><el-option v-for="u in users" :key="u.userId||u.id" :label="String(u.userName||u.username||u.userId||u.id)" :value="u.userId||u.id" /></el-select></el-form-item><el-form-item label="课程"><el-select v-model="form.courseId" filterable style="width:100%"><el-option v-for="c in courses" :key="c.course.courseId" :label="c.course.name" :value="c.course.courseId" /></el-select></el-form-item><el-form-item label="服务器"><el-select v-model="form.agentId" style="width:100%"><el-option v-for="a in agents" :key="a" :label="a" :value="a" /></el-select></el-form-item><el-form-item label="槽位"><el-select v-model="form.slotNumber" style="width:100%"><el-option v-for="s in availableSlots" :key="s.agentId+'-'+s.slotNumber" :label="'槽位 '+s.slotNumber+(s.userId?'（已绑定）':'（可用）')" :value="s.slotNumber" :disabled="!!s.userId" /></el-select></el-form-item><el-form-item label="标注模板"><el-input v-model="form.annotationTemplateId" /></el-form-item><el-form-item label="标注版本"><el-input v-model.number="form.annotationTemplateVersion" /></el-form-item><el-form-item label="编辑模板"><el-input v-model="form.editorTemplateId" /></el-form-item><el-form-item label="编辑版本"><el-input v-model.number="form.editorTemplateVersion" /></el-form-item></el-form><span slot="footer"><el-button @click="createDialog=false">取消</el-button><el-button type="primary" :loading="creating" @click="create">创建</el-button></span></el-dialog></section></template>
<script>
import { listAdminTrainingEnvironments, listAdminTrainingSlots, createAdminTrainingEnvironment, startAdminTrainingEnvironment, stopAdminTrainingEnvironment, restoreAdminTrainingEnvironment, deleteAdminTrainingEnvironment } from '@/api/TrainingEnvironments'
import { listAdminCourses } from '@/api/Courses'
import request from '@/utils/request'
export default { data: () => ({ loading:false, creating:false, createDialog:false, environments:[], slots:[], users:[], courses:[], form:{ userId:null, courseId:null, agentId:'', slotNumber:null, annotationTemplateId:'', annotationTemplateVersion:null, editorTemplateId:'', editorTemplateVersion:null } }), computed:{ agents(){return [...new Set(this.slots.map(s=>s.agentId))]}, availableSlots(){return this.slots.filter(s=>!this.form.agentId||s.agentId===this.form.agentId)}}, async created(){await Promise.all([this.load(),this.loadSlots(),this.loadOptions()])}, methods:{ async load(){this.loading=true;try{const r=await listAdminTrainingEnvironments();this.environments=r.data||[]}finally{this.loading=false}}, async loadSlots(){const r=await listAdminTrainingSlots();this.slots=r.data||[]}, async loadOptions(){const [u,c]=await Promise.all([request.get('/admin/users'),listAdminCourses()]);this.users=u.data||[];this.courses=c.data||[]}, pending(r){return ['CREATING','STARTING','STOPPING','RESTORING','WAITING_DEPENDENCY'].includes(r.actualState)}, async create(){this.creating=true;try{await createAdminTrainingEnvironment(this.form);this.createDialog=false;this.$message.success('创建任务已提交');await this.load()}finally{this.creating=false}}, async operate(r,a){await (a==='start'?startAdminTrainingEnvironment:stopAdminTrainingEnvironment)(r.environmentId);await this.load()}, async restore(r){await this.$confirm('确认还原环境？','提示',{type:'warning'});await restoreAdminTrainingEnvironment(r.environmentId);await this.load()}, async remove(r){await this.$confirm('确认删除已停止环境？','提示',{type:'warning'});await deleteAdminTrainingEnvironment(r.environmentId);await this.load()} } }
</script>
